// n8n Code node "Read the Message" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// Turns one Telegram update into: who wrote, in which chat, and what they want: help, a page from a product link, an admin command
// (/shops, /status, /on, /off), a brand intake (/intake), /stop (running brand intakes) or a tap on one of the bot's buttons.
const update = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s);
const cq = update.callback_query;
if (cq) {  // a tap on a button the bot sent (the confirm / cancel buttons of /on and /off)
  const chat = (cq.message || {}).chat || {};
  const from = cq.from || {};
  const name = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'there';
  const base = { chat_id: esc(chat.id), chat_type: esc(chat.type), user_id: esc(from.id), name, text: '', callback_id: esc(cq.id) };
  if (!chat.id || chat.type !== 'private' || from.is_bot) return [{ json: { ...base, kind: 'ignore' } }];
  return [{ json: { ...base, kind: 'button', data: esc(cq.data).slice(0, 64) } }];
}
const msg = update.message || update;
const chat = msg.chat || {};
const from = msg.from || {};
const text = String(msg.text || '').trim();
const name = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'there';
const base = { chat_id: String(chat.id || ''), chat_type: String(chat.type || ''), user_id: String(from.id || ''), name, text, callback_id: '' };

// group chats, channels, other bots and empty updates are ignored: the bot only talks one to one
if (!chat.id || chat.type !== 'private' || from.is_bot) return [{ json: { ...base, kind: 'ignore' } }];

// a message that looks like a password, token or key is never used (the person is asked to delete it)
const secret = /\bshp(at|ca|ss|tka)_[0-9a-z]{8,}/i.test(text) || /\b[0-9]{8,10}:[A-Za-z0-9_-]{30,}\b/.test(text)
  || /\b[0-9a-f]{32,}\b/i.test(text) || /\beyJ[A-Za-z0-9_-]{20,}\./.test(text) || /\bsk-ant-[A-Za-z0-9_-]{10,}/.test(text);
if (secret) return [{ json: { ...base, kind: 'secret' } }];

if (/^\/(start|help)\b/i.test(text) || !text) return [{ json: { ...base, kind: 'help' } }];

// a brand intake before a redesign: /intake <the store's address> (19 Oct 2026; runs on GitHub, the Drive link comes back here)
const intake = text.match(/^\/intake(?:@[A-Za-z0-9_]+)?(?:\s+([\s\S]*))?$/i);
if (intake) return [{ json: { ...base, kind: 'intake', arg: String(intake[1] || '').trim().slice(0, 200) } }];

// stop a running brand intake: /stop lists them, each with a Stop button (19 Oct 2026)
if (/^\/stop(?:@[A-Za-z0-9_]+)?\s*$/i.test(text)) return [{ json: { ...base, kind: 'stop' } }];

// admin commands: /shops, /status <shop>, /on <shop>, /off <shop> (the bot's @name may follow the command)
const cmd = text.match(/^\/(shops|status|on|off)(?:@[A-Za-z0-9_]+)?(?:\s+([\s\S]*))?$/i);
if (cmd) return [{ json: { ...base, kind: 'command', command: cmd[1].toLowerCase(), arg: String(cmd[2] || '').trim().slice(0, 100) } }];

// the first link in the message; everything else is the note for the designer
const m = text.match(/https?:\/\/[^\s<>"]+/i) || text.match(/\b(?:[a-z0-9-]+\.)+[a-z]{2,}\/[^\s<>"]*/i);
if (!m) return [{ json: { ...base, kind: 'nolink' } }];
const product_link = m[0].replace(/[).,;!?]+$/, '');
const note = (text.slice(0, m.index) + ' ' + text.slice(m.index + m[0].length)).replace(/\s+/g, ' ').trim().slice(0, 1500);
return [{ json: { ...base, kind: 'link', product_link, note } }];

// n8n Code node "Who Is It" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// Only people in the data table dtj_bot_users (active) may use the bot. Roles: requester (sends links), designer (also gets told
// when a page waits for Claude Code), admin (both, plus the app switch: /shops, /status, /on, /off).
// Output: one item with action
//   design -> start a page (Store Factory: New Page)
//   switch -> an admin's switch command or button tap: the shop is found after the install catcher's list ("Pick the Shop")
//   intake -> start a brand intake on GitHub ("Start Brand Intake")
//   stop   -> /stop or a Stop tap: GitHub's list of brand intake runs ("List Intakes"), then "Stop Plan"
//   brief  -> the answer to "collect the brand's data first?" after a page was started: saved on the brief ("Note the Choice")
//   seo    -> a tap on the Monday SEO report's Yes / No: handed to "SEO Engine: Weekly Report" ("SEO Answer"), which checks it
//   reply  -> just answer
const msg = $('Read the Message').first().json;
if (msg.kind === 'ignore') return [];
const users = $('Load Bot Users').all().map((i) => i.json).filter((u) => u && u.telegram_user_id && u.active !== false);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const reply = (text) => [{ json: { action: 'reply', chat_id: msg.chat_id, text } }];
const me = users.find((u) => String(u.telegram_user_id).trim() === msg.user_id);
const roleOf = (u) => String((u && u.role) || '').toLowerCase().trim();
const BUTTON_SECONDS = 120;

if (msg.kind === 'secret') {
  return reply('That looks like a password or a key. Please delete your message now (press and hold it, then Delete). '
    + 'Never send passwords or keys here, or in any chat.');
}
if (!me) {
  return reply('Hi ' + esc(msg.name) + '. This bot is only for the DTJ team. To get access, send Harsh this number: '
    + esc(msg.user_id));
}
const isAdmin = roleOf(me) === 'admin';
const myName = me.name || msg.name;
if (msg.kind === 'help') {
  return reply('Hi ' + esc(myName) + '! Send me a product link from the shop\'s website and I will start a full '
    + 'product page in the shop\'s draft theme.\n\nExample:\nhttps://myshop.com/products/my-product lead with the glow, real rating 4.6 on Judge.me\n\n'
    + '- The link must have /products/ in it (not a Shopify admin link).\n'
    + '- Anything after the link is a note for the designer.\n'
    + '- I send you the preview link here when the page is ready. Nothing goes live without Harsh.'
    + '\n\nBefore a redesign: /intake shop.com collects the shop\'s pictures, videos, colours and details into Google Drive.'
    + ' /stop shows the intakes running now, each with a Stop button.'
    + (isAdmin ? '\n\nAdmin: /shops lists every shop the switch reaches and whether its DTJ apps are on, /status shop shows one shop, '
      + '/off shop and /on shop switch all its DTJ apps (you confirm with a button).' : ''));
}
// a brand intake (19 Oct 2026, Harsh: "scrapes everything and uploads to the google drive"): GitHub Actions runs it ("Brand intake"
// workflow on the repo's default branch) and answers in this chat with the Drive folder's link. Anyone on the bot may ask.
if (msg.kind === 'intake') {
  const store = /^(https?:\/\/)?([A-Za-z0-9-]+\.)+[A-Za-z]{2,}(\/\S*)?$/.test(msg.arg) ? msg.arg : '';
  if (!store) {
    return reply('Send the shop\'s address after /intake, for example:\n/intake freesoul.com\n\n'
      + 'I read the shop\'s public pages (pictures and videos of up to 20 products, logo, colours, fonts, policies) and send you the '
      + 'Google Drive folder here in a few minutes.');
  }
  return [{ json: { action: 'intake', chat_id: msg.chat_id, store, requested_by: myName,
    body: { ref: 'chore/initial-import', inputs: { store, requested_by: myName, telegram_chat_id: msg.chat_id } } } }];
}
// "collect the brand's data first?" (19 Oct 2026, Harsh: "it should ask me if it should run the scraper or not and using the data
// available it should start designing"): the Yes / No buttons under "Intake Question" carry the brief's row id. Anyone on the bot.
if (msg.kind === 'button' && String(msg.data || '').startsWith('brief:')) {
  const b = String(msg.data).match(/^brief:(intake|skip):(\d{1,9})$/);
  if (!b) return reply('That button is not valid any more.');
  return [{ json: { action: 'brief', chat_id: msg.chat_id, row_id: Number(b[2]), brand_intake: b[1] === 'intake' ? 'yes' : 'no', by: myName } }];
}
// stopping a brand intake (19 Oct 2026, Harsh: "add a stop feature so it can stop any ongoing specific task"; he chose brand intakes
// only): /stop lists the intakes running on GitHub, each with a Stop button; the Stop button under an intake's progress bar stops
// that run. "Stop Plan" checks that the run is a brand intake that is still going before anything is cancelled. Anyone on the bot.
if (msg.kind === 'stop') return [{ json: { action: 'stop', mode: 'list', chat_id: msg.chat_id, run_id: '', by: myName } }];
if (msg.kind === 'button' && String(msg.data || '').startsWith('stop:')) {
  const s = String(msg.data).match(/^stop:intake:(\d{1,20})$/);
  if (!s) return reply('That button is not valid any more.');
  return [{ json: { action: 'stop', mode: 'cancel', chat_id: msg.chat_id, run_id: s[1], by: myName } }];
}
// the Monday SEO fixes batch (19 Oct 2026): Yes / No under the report "SEO Engine: Weekly Report" sends to the admins, and the
// teammate's "Harsh can't be reached" confirm. That workflow checks the batch, the person and the one-answer rule (CLAUDE.md rule 2).
if (msg.kind === 'button' && String(msg.data || '').startsWith('seo:')) {
  const s = String(msg.data).match(/^seo:(yes|no|yesnr|cancel):(\d{1,9})$/);
  if (!s) return reply('That button is not valid any more.');
  return [{ json: { action: 'seo', chat_id: msg.chat_id, row_id: Number(s[2]), answer: s[1], by: myName, user_id: msg.user_id } }];
}
if (msg.kind === 'nolink') {
  return reply('Please send a product link from the shop\'s website (it has /products/ in it). You can add a note after the link.');
}

// ---- the app switch (admins only). Which shops exist is the install catcher's to say, so the shop is matched in "Pick the Shop".
if (msg.kind === 'command' || msg.kind === 'button') {
  if (!isAdmin) return reply('Only an admin can see or switch the DTJ apps of a shop.');
  const otherAdmins = users.filter((u) => roleOf(u) === 'admin' && String(u.telegram_user_id).trim() !== msg.user_id)
    .map((u) => String(u.telegram_user_id).trim());
  const ask = { action: 'switch', chat_id: msg.chat_id, actor: myName, admins: otherAdmins, command: msg.command, arg: msg.arg || '',
    state: '', client: '' };
  if (msg.kind === 'button') {
    if (msg.data === 'lic:cancel') return reply('Cancelled. Nothing was switched.');
    const b = msg.data.match(/^lic:(on|off):([a-z0-9-]+):(\d{9,11})$/);
    if (!b) return reply('That button is not valid any more. Send the command again.');
    const age = Math.floor(Date.now() / 1000) - Number(b[3]);
    if (age < 0 || age > BUTTON_SECONDS) return reply('That button has expired (it works for 2 minutes). Send the command again.');
    return [{ json: { ...ask, command: 'tap', state: b[1] === 'on' ? 'active' : 'inactive', client: b[2] } }];
  }
  if (msg.command !== 'shops' && !msg.arg) return reply('Which shop? For example: /' + msg.command + ' test store. Send /shops for the list.');
  return [{ json: ask }];
}

// ---- a product link: start a page
const designers = users.filter((u) => ['designer', 'admin'].includes(roleOf(u))).map((u) => String(u.telegram_user_id).trim());
return [{ json: {
  action: 'design', chat_id: msg.chat_id, product_link: msg.product_link, note: msg.note,
  requested_by: myName + ' (Telegram)', requester_name: myName, requester_id: msg.user_id,
  designers: [...new Set(designers)],
} }];

// n8n Code node "Write the Answers" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// After "Store Factory: New Page" ran: one message for the person who asked and, when a page was started, one for each designer
// (a designer who asked gets both in one message). Every item is { chat_id, text } for the "Send" node (HTML mode, text escaped).
const ask = $('Who Is It').first().json;
const res = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
if (!res.ok) return [{ json: { chat_id: ask.chat_id, text: esc(res.message || 'That did not work. Please ask Harsh.') } }];

const what = (res.handle ? res.handle : 'your page') + (res.store_name ? ' on ' + res.store_name : '');
const toDesigner = 'New page waiting (brief ' + esc(res.row_id) + ') from ' + esc(ask.requester_name) + ': ' + esc(what) + '.\n'
  + 'Open Claude Code in the dtj-agency-automation folder and type:\nhandle the Claude Code trigger in n8n';
const askerIsDesigner = (ask.designers || []).includes(ask.requester_id);
const out = [{ json: { chat_id: ask.chat_id, text: 'Got it: designing ' + esc(what) + ' (brief ' + esc(res.row_id) + ').\n'
  + (askerIsDesigner ? '\n' + toDesigner : 'A designer will start it on their laptop; I will send you the preview link here when it is ready.') } }];
for (const d of ask.designers || []) {
  if (d !== ask.requester_id) out.push({ json: { chat_id: d, text: toDesigner } });
}
return out;

// n8n Code node "Licence Calls" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// One request per app of every shop "Pick the Shop" chose, for the install catcher's /licence (the HTTP step "Ask the Switch" sends
// each one with the bot's key from the n8n credential "DTJ Catcher Bot Key"). The apps come from the catcher's own list, so client
// copies (<client>-blocks / -sections / -sections2) and DTJ's original apps on organization stores are asked the same way.
const a = $input.first().json || {};
const ts = Math.floor(Date.now() / 1000);
const out = [];
for (const s of a.shops || []) {
  for (const p of s.apps || []) {
    const body = a.state === 'status'
      ? { app: p.app, state: 'status', ts }
      : { app: p.app, state: a.state, ts, approved_by: a.approved_by, reason: a.reason || '' };
    out.push({ json: { app: p.app, label: String(p.label || p.app).split(' - ')[0], client: s.client, body: JSON.stringify(body) } });
  }
}
return out;

// n8n Code node "Licence Report" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// Turns the catcher's answers (full responses: statusCode + body, one per app, in the order of "Licence Calls") into the message for
// the admin who asked, grouped per shop, and, after a switch, a note to every other admin. Every item out is { chat_id, text } for
// the "Send" step.
const a = $('Pick the Shop').first().json;
const calls = $('Licence Calls').all().map((i) => i.json);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parse = (b) => { if (b && typeof b === 'object') return b; try { return JSON.parse(String(b || '{}')); } catch (e) { return {}; } };
const word = (v) => (v === 'active' ? 'ON' : v === 'inactive' ? 'OFF' : v ? String(v) : 'not set (blocks hidden)');
const rows = $input.all().map((it, i) => {
  const r = it.json || {};
  const code = Number(r.statusCode || (r.error ? 0 : 200));
  const body = parse(r.body !== undefined ? r.body : r);
  const call = calls[i] || {};
  return { label: call.label || 'App ' + (i + 1), client: call.client || '', code, body, error: String(body.error || '') };
});
const line = (r) => {
  if (r.code === 200 && a.state === 'status') return r.label + ': ' + word(r.body.licence);
  if (r.code === 200) return r.label + ': ' + word(r.body.before) + ' -> ' + word(r.body.after) + (r.body.verified ? ' (checked)' : ' (NOT confirmed)');
  if (r.code === 404 && /no store key|has not installed/i.test(r.error)) return r.label + ': not installed on the shop';
  if (r.code === 404 && /organization/i.test(r.error)) return r.label + ': DTJ\'s app is not installed there, or the shop is outside DTJ\'s Shopify organization';
  if (r.code === 404) return r.label + ': not connected (' + esc(r.error || 'not installed') + ')';
  if (r.code === 401) return r.label + ': the bot\'s key was refused (ask Harsh to check the credential "DTJ Catcher Bot Key")';
  return r.label + ': failed (' + esc(r.error || ('HTTP ' + r.code)) + ')';
};
const block = (s) => rows.filter((r) => r.client === s.client).map(line).join('\n');
const head = (s) => esc(s.name) + ' (' + esc(s.shop) + (s.kind === 'dtj apps' ? ', DTJ\'s own apps' : '') + ')';
const fit = (text) => (text.length > 4000 ? text.slice(0, 3990) + '\n...' : text);  // Telegram's limit is 4096 characters

if (a.listing) {
  const parts = (a.shops || []).map((s) => head(s) + '\n' + block(s));
  const rest = (a.missing || []).length ? '\n\nSet up for pages, but not on the switch yet: ' + a.missing.map(esc).join(', ') + ' (ask Harsh).' : '';
  const example = (a.shops || [])[0] ? '\n\nUse a name with /status, /on or /off, for example: /status ' + esc(a.shops[0].name) : '';
  return [{ json: { chat_id: a.chat_id, text: fit('Shops on the switch:\n\n' + parts.join('\n\n') + rest + example) } }];
}
const shop = (a.shops || [])[0] || { name: '?', shop: '?', client: '' };
if (a.state === 'status') return [{ json: { chat_id: a.chat_id, text: fit('DTJ apps on ' + head(shop) + ':\n' + block(shop)) } }];

const ok = rows.length > 0 && rows.every((r) => r.code === 200 && r.body.verified);
const word2 = a.state === 'active' ? 'ON' : 'OFF';
const lines = block(shop);
const top = ok ? 'Done: all DTJ apps on ' + esc(shop.name) + ' are ' + word2 + '.' : 'Not everything switched on ' + esc(shop.name) + '. Check the lines below.';
const out = [{ json: { chat_id: a.chat_id, text: fit(top + '\n' + lines) } }];
for (const id of a.admins || []) {
  out.push({ json: { chat_id: id, text: fit(esc(a.actor) + ' switched ' + word2 + ' the DTJ apps on ' + esc(shop.name) + ' via Telegram.\n' + lines) } });
}
return out;

// n8n Code node "Pick the Shop" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// Input: the install catcher's list of every shop the switch reaches ("Ask for the Shop List": full response, statusCode + body):
// client app copies AND stores in DTJ's own organization running DTJ's original apps (Harsh, 12 Oct 2026: "on every store we work
// on the switch must work"). Finds the shop the admin named and decides the next step. Output: one item with action
//   licence -> ask the catcher about (or switch) every app of `shops`: status for /shops and /status, active|inactive after a tap
//   confirm -> send the "Yes, switch ..." / "Cancel" buttons
//   reply   -> just answer
// dtj_stores ("Load Shops") only adds friendlier names and the shop's other addresses, and shows shops set up for pages whose apps
// are not on the switch yet.
const ask = $('Who Is It').first().json;
const res = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const reply = (text) => [{ json: { action: 'reply', chat_id: ask.chat_id, text } }];
const parse = (b) => { if (b && typeof b === 'object') return b; try { return JSON.parse(String(b || '{}')); } catch (e) { return {}; } };
const code = Number(res.statusCode || (res.error ? 0 : 200));
const body = parse(res.body !== undefined ? res.body : res);
if (code === 401) {
  return reply('The install service refused the bot\'s key (ask Harsh to check the n8n credential "DTJ Catcher Bot Key"). Nothing was changed.');
}
if (code !== 200 || !Array.isArray(body.shops)) {
  const why = body.error || (typeof res.error === 'string' ? res.error : (res.error && res.error.message)) || ('HTTP ' + code);
  return reply('I could not reach the install service (' + esc(why) + '). Nothing was changed. Please try again in a minute.');
}

const low = (x) => String(x == null ? '' : x).toLowerCase().trim();
const rows = $('Load Shops').all().map((i) => i.json).filter((r) => r && r.myshopify_domain && r.active !== false);
const stem = (r) => (String(r.client_registry || '').match(/clients\/([a-z0-9-]+)\.json$/) || [])[1] || '';
const shops = body.shops.map((s) => {
  const row = rows.find((r) => low(r.myshopify_domain) === low(s.shop) || stem(r) === s.client);
  const name = (row && row.store_name) || s.name || s.client;
  const names = [name, s.name, s.client, s.shop, ...(row ? [row.myshopify_domain, ...String(row.other_domains || '').split(',')] : [])]
    .map(low).filter(Boolean);
  return { client: s.client, shop: s.shop, name, kind: s.kind, apps: (s.apps || []).map((a) => ({ app: a.app, label: a.label })), names };
});
const missing = rows.filter((r) => !shops.some((s) => low(s.shop) === low(r.myshopify_domain) || s.client === stem(r)))
  .map((r) => ({ name: r.store_name || r.myshopify_domain, names: [r.store_name, r.myshopify_domain, stem(r), ...String(r.other_domains || '').split(',')].map(low).filter(Boolean) }));
const plain = (s) => ({ client: s.client, shop: s.shop, name: s.name, kind: s.kind, apps: s.apps });
const licence = (state, list, extra) => [{ json: { action: 'licence', chat_id: ask.chat_id, state, shops: list.map(plain), listing: false,
  missing: [], approved_by: '', reason: '', actor: ask.actor, admins: [], ...extra } }];

if (ask.command === 'tap') {
  const shop = shops.find((s) => s.client === ask.client);
  if (!shop) return reply('That shop is not on the switch any more. Nothing was switched.');
  const word = ask.state === 'active' ? 'on' : 'off';
  return licence(ask.state, [shop], { approved_by: ask.actor + ' via Telegram', reason: 'Telegram /' + word, admins: ask.admins || [] });
}
if (ask.command === 'shops') {
  if (!shops.length) {
    return reply('No shop is on the switch yet.' + (missing.length ? ' Set up for pages only: ' + missing.map((m) => esc(m.name)).join(', ') + '.' : ''));
  }
  return licence('status', shops, { listing: true, missing: missing.map((m) => m.name) });
}

const q = low(ask.arg).replace(/^https?:\/\//, '').replace(/\/.*$/, '');
let found = shops.filter((s) => s.names.includes(q));
if (!found.length) found = shops.filter((s) => s.names.some((n) => n.includes(q)));
if (!found.length) {
  const pagesOnly = missing.find((m) => m.names.includes(q) || m.names.some((n) => n.includes(q)));
  if (pagesOnly) return reply(esc(pagesOnly.name) + ' is set up for pages, but its DTJ apps are not on the switch yet. Ask Harsh to add it.');
  return reply('No shop matches "' + esc(ask.arg) + '". Send /shops for the list.');
}
if (found.length > 1) {
  return reply('More than one shop matches "' + esc(ask.arg) + '": ' + found.map((s) => esc(s.name)).join(', ') + '. Please be more specific.');
}
const shop = found[0];
if (ask.command === 'status') return licence('status', [shop], {});
const off = ask.command === 'off';
const word = off ? 'OFF' : 'ON';
const yes = 'lic:' + ask.command + ':' + shop.client + ':' + Math.floor(Date.now() / 1000);
if (yes.length > 64) return reply('That shop\'s name is too long for a Telegram button. Ask Harsh to switch it with licence_call.py.');
return [{ json: { action: 'confirm', chat_id: ask.chat_id,
  text: 'Switch ' + word + ' all DTJ apps on ' + esc(shop.name) + ' (' + esc(shop.shop) + ')?\n'
    + (off ? 'Every DTJ block disappears from that shop for its shoppers at once.' : 'Every DTJ block comes back on that shop at once.')
    + '\nTap the button within 2 minutes.',
  yes_text: 'Yes, switch ' + word, yes_data: yes } }];

// n8n Code node "Intake Started" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// After "Start Brand Intake" asked GitHub to run the "Brand intake" workflow: GitHub answers 204 when the run is queued. The run itself
// sends the Drive link to this chat when it is done (.github/workflows/brand-intake.yml), so here we only say it started, or why not.
const ask = $('Who Is It').first().json;
const res = $input.first().json || {};
const status = Number(res.statusCode || 0);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
if (status === 204) {
  return [{ json: { chat_id: ask.chat_id, text: 'Started the brand intake for ' + esc(ask.store) + '. I will send the Google Drive '
    + 'folder here when it is ready (a few minutes; shops with many videos take longer).' } }];
}
const why = status === 401 || status === 403 ? 'the GitHub key in n8n is missing or not allowed to start runs'
  : status === 404 ? 'GitHub cannot find the "Brand intake" workflow on the main branch yet'
  : status === 422 ? 'GitHub did not accept the request'
  : 'GitHub did not answer';
return [{ json: { chat_id: ask.chat_id, text: 'Could not start the brand intake for ' + esc(ask.store) + ': ' + why
  + ' (' + (status || 'no answer') + '). Please tell Harsh.' } }];

// n8n Code node "Stop Plan" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// Stopping a brand intake (19 Oct 2026, Harsh: "add a stop feature so it can stop any ongoing specific task"; brand intakes only).
// After "List Intakes" asked GitHub for the latest runs of the "Brand intake" workflow (full response). Only a run of THAT workflow
// that is still going can be stopped, so a Stop button can never cancel anything else (the SEO runs, for example).
// Output: one or more items with action
//   cancel -> "Cancel the Intake" (run_id)
//   choose -> "Ask to Stop": one message per running intake, each with its own Stop button (/stop)
//   reply  -> just answer
const ask = $('Who Is It').first().json;
const res = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const reply = (text) => [{ json: { action: 'reply', chat_id: ask.chat_id, text } }];
const parse = (b) => { if (b && typeof b === 'object') return b; try { return JSON.parse(String(b || '{}')); } catch (e) { return {}; } };
const status = Number(res.statusCode || 0);
const body = parse(res.body !== undefined ? res.body : res);
if (status === 401 || status === 403) {
  return reply('GitHub refused the bot\'s key (the n8n credential "DTJ GitHub Actions"). Nothing was stopped. Please tell Harsh.');
}
if (status !== 200 || !Array.isArray(body.workflow_runs)) {
  return reply('I could not reach GitHub (' + (status || 'no answer') + '). Nothing was stopped. Please try again in a minute.');
}
const GOING = ['queued', 'in_progress', 'waiting', 'requested', 'pending'];
const store = (r) => String(r.display_title || '').replace(/^Brand intake:?\s*/, '').trim() || 'a store';
const ago = (r) => {
  const m = Math.max(0, Math.round((Date.now() - Date.parse(r.run_started_at || r.created_at || '')) / 60000));
  return Number.isFinite(m) ? (m < 1 ? 'less than a minute ago' : m + ' min ago') : 'a moment ago';
};
const runs = body.workflow_runs;

if (ask.mode === 'cancel') {
  const run = runs.find((r) => String(r.id) === String(ask.run_id));
  if (!run) return reply('That brand intake is not on GitHub\'s list of recent intakes. Nothing was stopped.');
  if (!GOING.includes(run.status)) {
    return reply('The brand intake for ' + esc(store(run)) + ' has already finished, so there is nothing to stop.');
  }
  return [{ json: { action: 'cancel', chat_id: ask.chat_id, run_id: String(run.id), store: store(run), by: ask.by } }];
}
const running = runs.filter((r) => GOING.includes(r.status));
if (!running.length) return reply('No brand intake is running right now.');
return running.map((r) => ({ json: { action: 'choose', chat_id: ask.chat_id,
  text: 'Running: brand intake for ' + esc(store(r)) + ', started ' + ago(r) + '.', stop_data: 'stop:intake:' + r.id } }));

// n8n Code node "Stop Report" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// After "Cancel the Intake" asked GitHub to cancel one brand intake run (full response): GitHub answers 202 when it starts cancelling.
// The run itself then closes its progress message and says in the chat that it was stopped (.github/workflows/brand-intake.yml).
const ask = $('Stop Plan').first().json;
const res = $input.first().json || {};
const status = Number(res.statusCode || 0);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let text;
if (status === 202) {
  text = 'Stopping the brand intake for ' + esc(ask.store) + ' (asked by ' + esc(ask.by) + '). Its progress message will say when it has '
    + 'stopped. Files it already put in Google Drive stay there.';
} else if (status === 409) {
  text = 'The brand intake for ' + esc(ask.store) + ' had already finished, so there was nothing to stop.';
} else {
  const why = status === 401 || status === 403 ? 'the GitHub key in n8n is missing or not allowed to stop runs' : 'GitHub did not accept it';
  text = 'Could not stop the brand intake for ' + esc(ask.store) + ': ' + why + ' (' + (status || 'no answer') + '). Please tell Harsh.';
}
return [{ json: { chat_id: ask.chat_id, text } }];

// n8n Code node "Intake Question" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// After "Store Factory: New Page" started a page: ask the person who sent the link whether the designer should collect the brand's
// data first (19 Oct 2026, Harsh: "if i am starting the design of a product page or homepage it should ask me if it should run the
// scraper or not and using the data available it should start designing"). The tap is saved on the brief (column brand_intake) by
// "Note the Choice"; the designer's Claude Code reads it before designing (request_page_design.js, step 2).
// Output: one item for "Ask About Intake" (the question with a Yes and a No button), or nothing when no page was started.
const ask = $('Who Is It').first().json;
const res = $input.first().json || {};
if (!res.ok || !res.row_id) return [];
return [{ json: {
  chat_id: ask.chat_id,
  text: 'One question before the designer starts brief ' + res.row_id + ': collect the brand\'s data first? That reads its website '
    + '(product pictures and videos, logo, colours, fonts, policies; a few minutes) and the page is designed from it.',
  yes_data: 'brief:intake:' + res.row_id,
  no_data: 'brief:skip:' + res.row_id,
} }];

// n8n Code node "Choice Noted" in "Store Factory: Telegram Bot" (mode: Run Once for All Items).
// After "Note the Choice" saved the answer to "collect the brand's data first?" on the brief (dtj_client_intake.brand_intake):
// tell the person what the designer will do. "Note the Choice" gives back the updated row, or nothing when the brief is gone.
const ask = $('Who Is It').first().json;
const row = ($input.all().map((i) => i.json).find((r) => r && r.id) || null);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
if (!row) return [{ json: { chat_id: ask.chat_id, text: 'That page request (brief ' + esc(ask.row_id) + ') is not on the list any more. Nothing was changed.' } }];
const brand = row.brand_name ? ' for ' + esc(row.brand_name) : '';
let text = ask.brand_intake === 'yes'
  ? 'Noted: the designer will collect the brand\'s data first' + brand + ' (pictures, colours, fonts, policies), then design the page from it.'
  : 'Noted: the designer will design the page' + brand + ' with the data we already have, without collecting it again.';
if (row.page_status) {
  text += '\nThis page is already marked "' + esc(row.page_status) + '", so tell the designer if it should be done again.';
}
return [{ json: { chat_id: ask.chat_id, text } }];
